import sys,random,string
sys.path.insert(0,'submission');import gateway
random.seed(2)
USER="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.!~*'()+"
TOK="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-.!%*_+`'~"
HOST='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-'
def ruser():
 out=''
 for _ in range(random.randint(1,10)):
  if random.random()<.2:
   c=random.choice(USER); out+='%'+format(ord(c),'02x')
  else: out+=random.choice(USER)
 return out
def rhost():
 labels=[]
 for _ in range(random.randint(1,4)):
  n=random.randint(1,10)
  s=random.choice(string.ascii_letters+string.digits)
  for i in range(n-2):s+=random.choice(HOST)
  if n>1:s+=random.choice(string.ascii_letters+string.digits)
  labels.append(s)
 return '.'.join(labels)+('.' if random.random()<.3 else '')
def ruri():
 if random.random()<.8:
  return random.choice(['sip','SIP','SiP'])+':'+ruser()+'@'+rhost()
 digits=str(random.randint(1,9))+''.join(random.choice(string.digits) for _ in range(random.randint(0,14)))
 return random.choice(['tel','TEL'])+':+'+digits
def bq():
 out='"'
 for _ in range(random.randint(0,10)):
  r=random.random()
  if r<.2: out+='\\'+random.choice(' "\t<>;,abc')
  elif r<.35: out+=random.choice(' \t<>;,abc')
  else: out+=random.choice(string.ascii_letters+string.digits+' :;,<>@.-_%')
 return out+'"'
def rdisp():
 if random.random()<.5:
  return ' '.join(''.join(random.choice(TOK) for _ in range(random.randint(1,8))) for _ in range(random.randint(1,4)))
 return bq()
def raddr():
 u=ruri()
 if random.random()<.5:
  return '<'+(' ' if random.random()<.3 else '')+u+('\t' if random.random()<.3 else '')+'>'
 return rdisp()+random.choice(['',' ','\t','  \t'])+'<'+(' ' if random.random()<.3 else '')+u+('\t' if random.random()<.3 else '')+'>'
def rtag():
 return random.choice(['',';tag='+''.join(random.choice(TOK) for _ in range(random.randint(1,20))),' ; tag = '+''.join(random.choice(TOK) for _ in range(random.randint(1,20)))+' '])
fails=0
for i in range(100000):
 v=raddr()+rtag()
 try: gateway.parse_from_or_to(v)
 except gateway.SIPFailure:
  fails+=1
  if fails<10: print('FAIL',repr(v))
print('fails',fails)
